#!/bin/sh
drush sql:query "SELECT cm.id, cm.contact_form, c.field_clinic_target_id, cm.subject, cm.name, cm.mail, LEFT(ag.field_agreement_value,40) AS agreement, LEFT(mr.field_media_release_agreement_value,40) AS media, SUBSTRING(a.field_mailing_address_address_line1,1,16) AS addr FROM contact_message cm JOIN contact_message__field_clinic c ON c.entity_id=cm.id AND c.deleted=0 JOIN contact_message__field_agreement ag ON ag.entity_id=cm.id AND ag.deleted=0 AND ag.langcode=cm.langcode JOIN contact_message__field_media_release_agreement mr ON mr.entity_id=cm.id AND mr.deleted=0 AND mr.langcode=cm.langcode LEFT JOIN contact_message__field_mailing_address a ON a.entity_id=cm.id AND a.deleted=0 WHERE cm.id=4943950"